// Junta todos os telefones do lote num array único para checar o WhatsApp de uma vez
const rows = $input.all().map(i => i.json);
const numeros = [...new Set(rows.map(r => String(r.telefone)))];
return [{ json: { numeros, rows } }];

const items = $input.all().map(i => i.json);
let lista = [];
if (items.length === 1) {
  const j = items[0];
  lista = Array.isArray(j) ? j : (j.data || j.result || [j]);
} else {
  lista = items.flatMap(j => Array.isArray(j) ? j : (j.data || j.result || [j]));
}

const digits = s => String(s || '').replace(/\D/g, '');

// gera as variantes com e sem o 9 (problema clássico BR)
function variantes(num) {
  const d = digits(num);
  const set = new Set([d]);
  if (d.length === 13 && d.substr(4, 1) === '9') set.add(d.substr(0, 4) + d.substr(5)); // tira o 9
  else if (d.length === 12) set.add(d.substr(0, 4) + '9' + d.substr(4));                // põe o 9
  return [...set];
}

// mapa de quem tem WhatsApp, indexado por TODAS as variantes
const existe = {};
for (const it of lista) {
  const num = digits(it && (it.number || it.jid));
  if (num && it.exists === true) for (const v of variantes(num)) existe[v] = true;
}

const rows = $('Monta lista de números1').first().json.rows;

// mantém só quem tem WhatsApp (comparando variantes)
const comWhats = rows.filter(r => variantes(r.telefone).some(v => existe[v] === true));

// 1 disparo por pessoa: mantém a primeira ocorrência de cada telefone
const porTelefone = {};
for (const r of comWhats) {
  const k = digits(r.telefone);
  if (!porTelefone[k]) porTelefone[k] = r;
}

// >>> TETO DIÁRIO <<< base ~286; com 300 envia tudo numa execução.
// Baixe esse valor (ex: 100) se quiser dividir em mais dias e aquecer o número.
const DAILY_CAP = 300;
return Object.values(porTelefone).slice(0, DAILY_CAP).map(r => ({ json: r }));

const item = $('Loop Visitantes1').first().json;

// ==== Template do Mês do Agricultor ====
// Mensagem FIXA (sem variáveis), conforme aprovado no Meta.
// Se o SEU template tiver variáveis no corpo ({{1}}, {{2}}...), preencha o array
// abaixo NA MESMA ORDEM. Se não tiver, deixe vazio (não manda 'components').
const bodyParams = []; // ex.: [item.candidato_email]

const template = {
  name: 'mes_do_agricultor',
  language: { code: 'pt_BR' }
};
if (bodyParams.length) {
  template.components = [
    { type: 'body', parameters: bodyParams.map(t => ({ type: 'text', text: String(t) })) }
  ];
}

const body = {
  messaging_product: 'whatsapp',
  to: String(item.telefone),
  type: 'template',
  template
};

return [{
  json: {
    resultado: body,
    telefone: item.telefone,
    candidato_id: item.candidato_id,
    whatsapp_number_id: '1123205217553260',
    template_usado: 'mes_do_agricultor',
    texto_log: 'Campanha Mês do Agricultor (template mes_do_agricultor)'
  }
}];

